package com.example.quanlybaotri.payment.application;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.example.quanlybaotri.maintenance.client.MaintenanceClient;
import com.example.quanlybaotri.payment.domain.*;
import com.example.quanlybaotri.payment.persistence.PaymentAttemptRepository;
import com.example.quanlybaotri.shared.api.ApiException;
import com.example.quanlybaotri.shared.security.CurrentUser.Actor;
import com.example.quanlybaotri.identity.domain.RoleName;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;

class PaymentServicePolicyTest {
    private MaintenanceClient maintenance;private PaymentAttemptRepository attempts;private VnpayClient vnpay;private PaymentService service;
    @BeforeEach void setUp(){maintenance=mock(MaintenanceClient.class);attempts=mock(PaymentAttemptRepository.class);vnpay=mock(VnpayClient.class);service=new PaymentService(maintenance,attempts,vnpay,new VnpayProperties(),new SimpleMeterRegistry());}
    @Test void positiveCostMustBePaidBeforeClosing(){UUID id=UUID.randomUUID();when(attempts.existsByTicketIdAndStatus(id,PaymentStatus.SUCCEEDED)).thenReturn(false);assertThatThrownBy(()->service.ensureSettled(id,new BigDecimal("100000"))).isInstanceOf(ApiException.class);when(attempts.existsByTicketIdAndStatus(id,PaymentStatus.SUCCEEDED)).thenReturn(true);assertThatCode(()->service.ensureSettled(id,new BigDecimal("100000"))).doesNotThrowAnyException();}
    @Test void zeroCostDoesNotRequirePayment(){UUID id=UUID.randomUUID();assertThatCode(()->service.ensureSettled(id,BigDecimal.ZERO)).doesNotThrowAnyException();verifyNoInteractions(attempts);}
    @Test void pendingOrSuccessfulPaymentBlocksReopening(){UUID id=UUID.randomUUID();when(attempts.existsByTicketIdAndStatus(id,PaymentStatus.PENDING)).thenReturn(true);assertThatThrownBy(()->service.ensureReopenAllowed(id)).isInstanceOf(ApiException.class);when(attempts.existsByTicketIdAndStatus(id,PaymentStatus.SUCCEEDED)).thenReturn(true);assertThatThrownBy(()->service.ensureReopenAllowed(id)).isInstanceOf(ApiException.class);}
    @Test void paymentOnlyBecomesAvailableAfterCustomerAcceptance(){UUID id=UUID.randomUUID();BigDecimal amount=new BigDecimal("100000");assertThat(service.snapshot(id,amount,"QUOTED",List.of()).status()).isEqualTo(TicketPaymentStatus.NOT_AVAILABLE);assertThat(service.snapshot(id,amount,"ACCEPTED",List.of()).status()).isEqualTo(TicketPaymentStatus.UNPAID);}
    @Test void ipnValidatesAndRecordsSuccessOnce(){UUID id=UUID.randomUUID();PaymentAttempt attempt=new PaymentAttempt(id,"TXN123",new BigDecimal("75000"),UUID.randomUUID(),"127.0.0.1",Instant.now().plusSeconds(900));when(vnpay.verifyCallback(anyMap())).thenReturn(true);when(vnpay.correctMerchant(anyMap())).thenReturn(true);when(vnpay.merchantAmount("7500000")).thenReturn(new BigDecimal("75000.00"));when(attempts.findByTxnRef("TXN123")).thenReturn(Optional.of(attempt));Map<String,String> fields=Map.of("vnp_TxnRef","TXN123","vnp_Amount","7500000","vnp_ResponseCode","00","vnp_TransactionStatus","00");assertThat(service.ipn(fields).RspCode()).isEqualTo("00");assertThat(service.ipn(fields).RspCode()).isEqualTo("02");verify(maintenance,times(1)).record(eq(id),eq("PAYMENT_SUCCEEDED"),anyString(),anyMap());}
    @Test void signedBrowserReturnSettlesPaymentWhenIpnCannotReachLocalEnvironment(){UUID id=UUID.randomUUID();PaymentAttempt attempt=new PaymentAttempt(id,"TXN456",new BigDecimal("125000"),UUID.randomUUID(),"127.0.0.1",Instant.now().plusSeconds(900));when(vnpay.verifyCallback(anyMap())).thenReturn(true);when(vnpay.correctMerchant(anyMap())).thenReturn(true);when(vnpay.merchantAmount("12500000")).thenReturn(new BigDecimal("125000.00"));when(attempts.findByTxnRef("TXN456")).thenReturn(Optional.of(attempt));Map<String,String> fields=Map.of("vnp_TxnRef","TXN456","vnp_Amount","12500000","vnp_ResponseCode","00","vnp_TransactionStatus","00");PaymentService.ReturnTarget target=service.paymentReturn(fields);assertThat(target.valid()).isTrue();assertThat(target.ticketId()).isEqualTo(id);assertThat(attempt.getStatus()).isEqualTo(PaymentStatus.SUCCEEDED);verify(maintenance).record(eq(id),eq("PAYMENT_SUCCEEDED"),anyString(),anyMap());}
    @Test void browserReturnRejectsMismatchedAmountWithoutChangingPayment(){UUID id=UUID.randomUUID();PaymentAttempt attempt=new PaymentAttempt(id,"TXN789",new BigDecimal("125000"),UUID.randomUUID(),"127.0.0.1",Instant.now().plusSeconds(900));when(vnpay.verifyCallback(anyMap())).thenReturn(true);when(vnpay.correctMerchant(anyMap())).thenReturn(true);when(vnpay.merchantAmount("100")).thenReturn(BigDecimal.ONE);when(attempts.findByTxnRef("TXN789")).thenReturn(Optional.of(attempt));Map<String,String> fields=Map.of("vnp_TxnRef","TXN789","vnp_Amount","100","vnp_ResponseCode","00","vnp_TransactionStatus","00");assertThat(service.paymentReturn(fields).valid()).isFalse();assertThat(attempt.getStatus()).isEqualTo(PaymentStatus.PENDING);verifyNoInteractions(maintenance);}
    @Test void customerCanReconcileOnlyTheirOwnExpiredPayment(){UUID ticketId=UUID.randomUUID(),ownerId=UUID.randomUUID(),attemptId=UUID.randomUUID();PaymentAttempt attempt=new PaymentAttempt(ticketId,"EXPIRED1",new BigDecimal("50000"),ownerId,"127.0.0.1",Instant.now().minusSeconds(60));when(attempts.findById(attemptId)).thenReturn(Optional.of(attempt));when(vnpay.query(eq(attempt),anyString())).thenReturn(new VnpayClient.QueryResult(Map.of("vnp_TxnRef","EXPIRED1","vnp_TmnCode","","vnp_ResponseCode","91")));Actor owner=new Actor(ownerId,"customer","Customer",Set.of(RoleName.REQUESTER),"token","CUSTOMER",UUID.randomUUID(),"ALL_SITES",Set.of());assertThat(service.reconcile(attemptId,owner,"127.0.0.1").status()).isEqualTo(PaymentStatus.FAILED);verify(maintenance).record(eq(ticketId),eq("PAYMENT_FAILED"),anyString(),anyMap());}
    @Test void customerCannotReconcileAnotherCustomersPayment(){UUID attemptId=UUID.randomUUID();PaymentAttempt attempt=new PaymentAttempt(UUID.randomUUID(),"EXPIRED2",new BigDecimal("50000"),UUID.randomUUID(),"127.0.0.1",Instant.now().minusSeconds(60));when(attempts.findById(attemptId)).thenReturn(Optional.of(attempt));Actor stranger=new Actor(UUID.randomUUID(),"customer","Customer",Set.of(RoleName.REQUESTER),"token","CUSTOMER",UUID.randomUUID(),"ALL_SITES",Set.of());assertThatThrownBy(()->service.reconcile(attemptId,stranger,"127.0.0.1")).isInstanceOf(ApiException.class);verify(vnpay,never()).query(any(),anyString());}
}
